import { withAuth } from "@workos-inc/authkit-nextjs";
import type { User as AuthUser } from "@workos-inc/node";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // WorkOS user id, set once the user has signed in through AuthKit.
  workosId?: string;
};

// In-memory store: resets on server restart. Swap for a database before shipping.
const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

function displayName(authUser: AuthUser): string {
  const full = [authUser.firstName, authUser.lastName].filter(Boolean).join(" ");
  return authUser.name || full || authUser.email.split("@")[0];
}

// Finds or creates the Notely user for a WorkOS identity. Existing users are
// linked by email only when WorkOS has verified that email, so nobody can claim
// an account by signing up with someone else's unverified address.
export async function upsertUserFromAuth(authUser: AuthUser): Promise<User> {
  const byWorkosId = users.find((u) => u.workosId === authUser.id);
  if (byWorkosId) {
    byWorkosId.email = authUser.email;
    return byWorkosId;
  }

  const email = authUser.email.toLowerCase();
  const byEmail = authUser.emailVerified
    ? users.find((u) => !u.workosId && u.email.toLowerCase() === email)
    : undefined;
  if (byEmail) {
    byEmail.workosId = authUser.id;
    return byEmail;
  }

  const user: User = {
    id: String(users.reduce((max, u) => Math.max(max, Number(u.id) || 0), 0) + 1),
    email: authUser.email,
    name: displayName(authUser),
    createdAt: new Date().toISOString().slice(0, 10),
    workosId: authUser.id,
  };
  users.push(user);
  return user;
}

// Returns the signed-in user, or undefined for signed-out visitors.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  if (!user) return undefined;
  return upsertUserFromAuth(user);
}

// Same as getCurrentUser, but redirects signed-out visitors to sign in.
export async function requireCurrentUser(): Promise<User> {
  const { user } = await withAuth({ ensureSignedIn: true });
  return upsertUserFromAuth(user);
}
